[Form]
public class AVADirPartyLookupBP extends FormRun implements DirIPersonNameLookupForm
{
    NumberSeqFormHandler            numberSeqFormHandler;
    FormRun                         callerForm;
    Common                          callerRecord;
    Object                          callerDataSource;
    DirPartyTable                   partyTable;
    QueryBuildRange                 dirTypeRange;
    DirPartyType                    dirType;
    QueryBuildRange                 partyNumberRange;
    DirPartyNumber                  partyNumber;
    DirPartyRecId                   party;
    TableId                         callerDataSet;
    DirPartyLookupEntitiesFilter    dirPartyLookupEntitiesFilter;
    FormReferenceGroupControl       referenceControl;
    DirSubNameSequenceType          namePart;
    boolean                         createNew;
    boolean                         canSelect;
    boolean                         notLookup;
    boolean                         continueFlag;
    boolean                         mergeLookup;
    boolean                         returnPersonNameComponents;
    container                       mergepartyNumbers;
    boolean                         nonUsersOnly;       // only show persons who are not users in the system

}

public void closeOk()
{
    if (!canSelect)
    {
        return;
    }

    DirPartyNumber selectedPartyNumber = createNew ? '' : dirPartyTable.PartyNumber;

    if (notLookup && !continueFlag)
    {
        switch (callerRecord.TableId)
        {
            case tableNum(DirPartyTable) :
                partyTable.PartyNumber = DirPartyTable::find(selectedpartyNumber).PartyNumber;

                if (!createNew)
                {
                    partyTable.modifiedField(fieldNum(DirPartyTable,PartyNumber));
                }
                break;

            default :
                this.closeOkExtended(callerRecord, DirPartyTable::find(selectedPartyNumber), createNew, callerDataSource, dirType);
                break;
        }

        if (callerDataSource)
        {
            callerDataSource.refresh();
        }
    }
    else
    {
        this.closeOkExtended(callerRecord, DirPartyTable::find(selectedPartyNumber), createNew, callerDataSource, dirType);
    }

    super();
}

