                            Object          _callerDataSource,
                            DirPartyType    _dirPartyType)
{
    // Extension method
}

public void closeSelect(str _selectString)
{
    if (!canSelect && !createNew)
    {
        return;
    }

    if (referenceControl)
    {
        super(_selectString);
        return;
    }

    DirPartyNumber selectedPartyNumber = createNew ? '' : dirPartyTable.PartyNumber;

    if (mergeLookup)
    {
        super(_selectString);
        return;
    }

    this.closeSelectExtended(callerRecord, DirPartyTable::find(selectedPartyNumber), createNew, callerDataSource);

    if (callerDataSource)
    {
        callerDataSource.refresh();
    }

    if (!canSelect)
    {
        return;
    }

    if (!createNew)
    {
        super(_selectString);
    }
}

