public DirPartyTable getPartyRecord()
{
    // OnlyFetchActive=Yes so retrieve the table fully.
    return DirPartyTable::findRec(dirPartyTable.RecId);
}

public DirPersonName getPersonName()
{
    return DirPersonName::find(dirPartyTable.RecId);
}

    public void init()
    {
        Args args = element.args();
        Object caller = args.caller();
        if (!args || !caller)
        {
            throw error("@SYS22539");
        }

        switch (args.parmEnumType())
        {
            case enumNum(DirPartyType):
                dirType = args.parmEnum();
                break;
            case enumNum(DirPartyLookupOption):
                dirType = DirPartyType::Person;
                nonUsersOnly = true;
                break;
            case enumNum(DirSubNameSequenceType):
                namePart = args.parmEnum();
                dirType = DirPartyType::Person;
                returnPersonNameComponents = true;
                break;

            default:
                dirType = DirPartyType::Organization;
                break;

        }

        if(caller is FormRun)
        {
            callerForm = caller;
        }
        else if (caller is FormControl)
        {
            FormControl control = caller;
            callerForm = control.formRun();
        }

        if (args.parmObject() != null)
        {
            dirPartyLookupEntitiesFilter = args.parmObject();
        }
        else
        {
            if (formHasMethod(callerForm, identifierStr(getEntityFilter)))
            {
                Object formObject = callerForm;
                dirPartyLookupEntitiesFilter = formObject.getEntityFilter();
            }
            else
            {
                dirPartyLookupEntitiesFilter = dirPartyLookupEntitiesFilter::generateDirPartyLookupEntitiesFilter();
            }
        }

        callerDataSet = args.dataset();
        if (callerDataSet)
        {
            callerDataSource = FormDataUtil::getFormDataSource(args.record());

            if (callerDataSource)
            {
                callerRecord = callerDataSource.cursor();
            }
            else
            {
                //lookups using DirUtility::namelookup will not have datasource
                callerRecord = args.record();
            }

            switch (callerRecord.TableId)
            {
                case tableNum(DirPartyTable) :
                    partyTable = callerRecord;
                    party =!notLookup?DirPartyTable::find(partyNumber).RecId:partyTable.RecId;
                    this.parmParty(party);
                    break;

                default :
                    this.formInitExtended(callerRecord, partyNumber, dirType);
                    break;
            }

            partyNumber = DirPartyTable::findRec(this.parmParty()).PartyNumber;
        }

        super();

        if (!notLookup)
        {
            this.selectMode(dirPartyTable_Name);
            continueButton.visible(false);
        }

        this.showControlsExtended(callerRecord, dirType, callerDataSet);

        if (dirType == DirPartyType::Person)
//        if (    dirType == DirPartyType::Person
//            ||  dirType == DirPartyType::Organization)
        {
            DirPartyTypeView_DS.object(fieldnum(DirPartyTypeView, Type)).visible(false);
            DirPartyTypeView_DS.query().dataSourceName(tablestr(DirPartyTypeView)).enabled(false);
        }

        element.selectRecordModeSelectedRecord(dirPartyTable);

        OkButton.enabled(false); // Disabling 'Select' confirmation button until user selects a record to avoid null selection.
    }

