void run()
{
    #Characters

    FormControl         callerControl = element.selectTarget();
    str                 filterStr = '';
    str                 filterTableStr = tableStr(DirPartyTable);
    str                 filterFieldStr = fieldStr(DirPartyTable, Name);
    DictField           dictField;
    DictType            dictType;
    FilterValue         filterValue;

    if (callerControl is FormReferenceGroupControl)
    {
        referenceControl = callerControl;

        dictField = new DictField(referenceControl.fieldBinding().tableId(), referenceControl.fieldBinding().fieldId());

        if (dictField)
        {
            dictType = new DictType(dictField.typeId());
        }

        if (referenceControl &&
        (referenceControl.extendedDataType() == extendedTypeNum(DirPersonRecId) ||
        (dictField && dictField.typeId() == extendedTypeNum(DirPersonRecId))) ||
        (dictType && dictType.isExtendedFrom(extendedTypeStr(DirPersonRecId))))
        {
            dirTypeRange.value(SysQuery::value(tableNum(DirPerson)));
            filterTableStr = tableStr(DirPerson);
            filterFieldStr = fieldStr(DirPerson, Name);
        }

        super();

        filterValue = referenceControl.filterValue(AbsoluteFieldBinding::construct(filterFieldStr, filterTableStr));

        if (filterValue)
        {
            filterStr = filterValue.value();

            if (filterStr)
            {
                this.selectMode(dirPartyTable_Name);
                dirPartyTable_Name.setFocus();
                dirPartyTable_ds.research();
            }
        }
    }
    else if (callerControl is FormStringControl)
    {
        super();

        if (!notLookup && !mergeLookup)
        {
            FormStringControl formStringControl = callerControl as FormStringControl;
            // User input values should be taken literally to maintain compatibility with the SysTableLookup functionality.
            filterStr = SysQueryRangeUtil::literalFilterValue(formStringControl.text());
        }
    }
    else
    {
        throw error(Error::wrongUseOfFunction(funcname()));
    }

    if (filterStr != '')
    {
        this.applyFilter(filterStr);
    }

    canSelect = false;
}

public void applyFilter(str _filterStr)
{
    DirPartyTable partyRecord;

    if (returnPersonNameComponents)
    {
        if (callerDataSet == tableNum(DirPersonName) && callerRecord.RecId)
        {
            DirPersonName personName = callerRecord as DirPersonName;
            select firstonly partyRecord where partyRecord.RecId == personName.Person;
        }
        else
        {
            FieldId nameFieldId;
            switch (namePart)
            {
                case DirSubNameSequenceType::FirstName :
                    nameFieldId = fieldNum(DirPersonName, FirstName);
                    break;
                case DirSubNameSequenceType::MiddleName :
                    nameFieldId = fieldNum(DirPersonName, MiddleName);
                    break;
                case DirSubNameSequenceType::LastName :
                    nameFieldId = fieldNum(DirPersonName, LastName);
                    break;
                case DirSubNameSequenceType::LastNamePrefix :
                    nameFieldId = fieldNum(DirPersonName, LastNamePrefix);
                    break;
            }

            QueryBuildDataSource personNameDataSource = SysQuery::findOrCreateDataSource(dirPartyTable_Q, tableNum(DirPersonName), tableNum(DirPartyTable));
            personNameDataSource.addLink(fieldNum(DirPartyTable, RecId), fieldNum(DirPersonName, Person));
            personNameDataSource.joinMode(JoinMode::ExistsJoin);

            QueryBuildRange namePartRange = SysQuery::findOrCreateRange(personNameDataSource, nameFieldId);
            namePartRange.status(RangeStatus::Hidden);
            namePartRange.value(this.getFilterQueryRangeValue(_filterStr));

            dirPartyTable_DS.executeQuery();
        }
    }
    else
    {
        if (partyNumber)
        {
            select firstonly partyRecord where partyRecord.PartyNumber == partyNumber;
        }
        else
        {
            partyRecord = DirPartyTable::findByName(_filterStr);
            if (partyRecord.RecId == 0)
            {
                QueryBuildDataSource organizationDataSource = dirPartyTable_DS.queryBuildDataSource();
                SysQuery::findOrCreateRange(organizationDataSource, fieldNum(DirPartyTable, Name)).value(this.getFilterQueryRangeValue(_filterStr));

                if (dirType != DirPartyType::None)
                {
                    SysQuery::findOrCreateRange(organizationDataSource, fieldNum(DirPartyTable, InstanceRelationType)).value(queryValue(DirPartyTable::type2RelationType(dirType)));
                }
                dirPartyTable_DS.executeQuery();
            }
        }
    }

    if (partyRecord)
    {
        element.args().lookupRecord(partyRecord);
        dirPartyTable_DS.research(false);
    }
}

public str getFilterQueryRangeValue(str _filterStr)
{
    return SysQuery::valueLikeAfter(_filterStr);
}

