}

public void executeQuery()
{
    QueryBuildRange         qbrRelationshipType;
    QueryBuildRange         qbrParentParty;
    XDSServices xds = new XDSServices();
    #DirParty

    // Trigger the DirPartyTable XDS policies by passing the context string
    xds.setXDSContext(0, #RestrictParty);

    if (dirPartyLookupEntitiesFilter.parmDisableAllEntityTypeFilters())
    {
        super();
        // Disable the DirPartyTable XDS policies by passing a blank context string
        xds.setXDSContext(0, '');
        return;
    }

    if (dirPartyLookupEntitiesFilter.parmFilterCurrentLegalEntity() == FilterStatus::Set)
    {
        QueryBuildRange qbrCurrentLegalEntity = SysQuery::findOrCreateRange(this.findOrAddRelationshipDataSource(), fieldNum(DirPartyRelationship, LegalEntityDataAreaId));
        qbrCurrentLegalEntity.value(SysQuery::value(curExt()));
        qbrCurrentLegalEntity.status(RangeStatus::Hidden);
    }

    if (dirPartyLookupEntitiesFilter.parmFilterRelationshipType() != '')
    {
        QueryBuildDataSource relationshipDataSource = this.findOrAddRelationshipDataSource();

        qbrRelationshipType = SysQuery::findOrCreateRange(relationshipDataSource, fieldNum(DirPartyRelationship, RelationshipTypeId));
        qbrRelationshipType.status(RangeStatus::Hidden);
        qbrRelationshipType.value(dirPartyLookupEntitiesFilter.parmFilterRelationshipType());

        qbrParentParty = SysQuery::findOrCreateRange(relationshipDataSource, fieldNum(DirPartyRelationship, ParentParty));
        qbrParentParty.status(RangeStatus::Hidden);
        qbrParentParty.value(queryValue(dirPartyLookupEntitiesFilter.parmFilterParentParty()));

        super();

        // Disable the DirPartyTable XDS policies by passing a blank context string
        xds.setXDSContext(0, '');
        return;
    }

    element.addRanges();

    super();
    // Disable the DirPartyTable XDS policies by passing a blank context string
    xds.setXDSContext(0, '');
}

private QueryBuildDataSource findOrAddRelationshipDataSource()
{
    QueryBuildDataSource relationshipDataSource = this.query().dataSourceTable(tableNum(DirPartyRelationship));
    if (!relationshipDataSource)
    {
        relationshipDataSource = this.query().dataSourceTable(tableNum(DirPartyTable)).addDataSource(tableNum(DirPartyRelationship));
        relationshipDataSource.addLink(fieldNum(DirPartyTable, RecId), fieldNum(DirPartyRelationship, ChildParty));
        relationshipDataSource.joinMode(JoinMode::ExistsJoin);
    }

    return relationshipDataSource;
}

public void init()
{
    QueryBuildDataSource    qbDirPartyTable;
    str                     queryCondition;

    QueryBuildDataSource    qbdsDirPartyView;
    QueryBuildRange         locQbr;
    DirPartyTable           locDirPartyTable;

    locDirPartyTable.partyType();

    super();

    // Add fields exclusively. DS DirPartyTable has Only Fetch Active Set as true. So , we need to add the below fields to be used by DS that joins to DirPartyTable
    dirPartyTable_ds.addFieldToSelectionList(fieldNum(DirPartyTable, PrimaryAddressLocation));
    dirPartyTable_ds.addFieldToSelectionList(fieldNum(DirPartyTable, PrimaryContactPhone));
    dirPartyTable_ds.addFieldToSelectionList(fieldNum(DirPartyTable, PrimaryContactEmail));
    dirPartyTable_ds.addFieldToSelectionList(fieldNum(DirPartyTable, NameAlias));

    qbDirPartyTable = this.query().dataSourceName(this.name());
    qbDirPartyTable.clearDynalinks();
    //qbDirPartyTable.clearLinks();
    qbDirPartyTable.clearRanges();

    qbdsDirPartyView =  this.query().dataSourceName('DirPartyView');

    queryCondition  = '((%1 == %2) || (%1 == %3))';
    locQbr  = qbdsDirPartyView.addRange(fieldNum (DirPartyView, Roletype));

    locQbr.value(queryValue(DirPartyRoleType::Customer));
    /*
    queryCondition  = '((%1 != %2) || (%3 != %4))'; // ( && (%5 == %6)))';
    locQbr.value(   strFmt( queryCondition,
                            fieldStr (CustTable, Party),
                            queryValue('0'),
                            fieldStr (smmBusRelTable, Party),
                            queryValue('0') )   ); //,
    //queryValue(DirPartyType::Organization) )   );
    */
    /*
    queryCondition  = '((%1.%2 != %3) || ((%4.%5 != %6))'; // && (%1.%5 == %6)))';
    locQbr  = qbDirPartyTable.addRange(fieldNum (CustTable, Party));
    locQbr.value(   strFmt( queryCondition,
                            this.query().dataSourceTable(tableNum(smmBusRelTable)).name(),
                            fieldStr (smmBusRelTable, Party),
                            queryValue('0'),
                            this.query().dataSourceTable(tableNum(CustTable)).name(),
                            fieldStr (CustTable, Party),
                            queryValue('0')
                            )   );
    */
    dirTypeRange = SysQuery::findOrCreateRange(qbDirPartyTable, fieldNum(DirPartyTable,InstanceRelationType));
    dirTypeRange.status(RangeStatus::Hidden);

    // Add range for Party type
    if (dirType != DirPartyType::None)
    {
        if (dirTypeRange)
        {
            if (dirType == DirPartyType::Person)
            {
                dirTypeRange.value(SysQuery::value(tableNum(DirPerson)));
            }
            else
            {
                dirTypeRange.value(SysQuery::valueNot(tableNum(DirPerson)));
            }
        }
    }

    if (partyNumber)
    {
        partyNumberRange = qbDirPartyTable.addRange(fieldNum(DirPartyTable,PartyNumber));
        if (partyNumberRange)
        {
            partyNumberRange.value(queryValue(partyNumber));
        }
    }

    if (mergeLookup)
    {
        qbDirPartyTable.addRange(fieldNum(DirPartyTable, RecId)).value(con2Str(mergepartyNumbers));
    }

    if (nonUsersOnly)
    {
        QueryBuildDataSource qbdsDirPersonUser = this.query().dataSourceName(tablestr(DirPartyTable)).addDataSource(tableNum(DirPersonUser));
        qbdsDirPersonUser.addLink(fieldNum(DirPartyTable,RecId),fieldnum(DirPersonUser,PersonParty),tableStr(DirPartyTable));
        qbdsDirPersonUser.joinMode(JoinMode::NoExistsJoin);
    }

}

