public boolean modified()
{
    boolean             ret;

    ret = super();
    if (ret)
    {
        if (!notLookup && partyNumberRange)
        {
            partyNumberRange.enabled(false);
        }
        dirPartyTable_Name.filter((this.text() == '')?'*':this.text());
        canSelect = true;

    }
    return ret;
}

void clicked()
{
    canSelect = true;
    super();

    if (referenceControl)
    {
        element.closeSelectRecord(dirPartyTable);
    }
    else
    {
        element.closeSelect(DirPartyTable.Name);
    }
}

void clicked()
{
    createNew = true;
    continueFlag = true;
    canSelect = true;
    element.closeOk();
}
